const fashionDefault={skin:1,hair:0,hairColor:0,eyes:0,lip:0,top:0,skirt:0,shoes:0,earrings:0,bag:0,necklace:0};
let look={...fashionDefault},fashionCategory='top',faceZoom=false;
try{const stored=JSON.parse(localStorage.getItem('alice-isabela-look'));for(const k in look)if(Number.isInteger(stored?.[k])&&stored[k]>=0&&stored[k]<4)look[k]=stored[k]}catch{}
const fashionOptions={
 top:['Camiseta casual','Blusa romântica','Jaqueta esportiva','Blusa de festa'],skirt:['Saia jeans','Saia floral','Saia esportiva','Saia de tule'],shoes:['Tênis','Sapatilhas','Tênis esportivos','Sandálias'],earrings:['Pérolas','Corações','Estrelas','Argolas'],bag:['Bolsa tiracolo','Bolsa de laço','Mochilinha','Bolsa de festa'],necklace:['Sem colar','Coração','Contas coloridas','Estrela'],hair:['Longo liso','Cachos','Dois coques','Curto'],hairColor:['Castanho','Preto','Loiro','Ruivo'],eyes:['Castanhos','Azuis','Verdes','Mel'],lip:['Natural','Rosa','Coral','Ameixa'],skin:['Tom claro','Tom dourado','Tom moreno','Tom escuro']};
const fashionLabels={top:'Blusas',skirt:'Saias',shoes:'Sapatos',earrings:'Brincos',bag:'Bolsas',necklace:'Colares',hair:'Cabelo',hairColor:'Cor do cabelo',eyes:'Olhos',lip:'Batom',skin:'Pele'};
const fashionIcons={top:'♧',skirt:'♙',shoes:'♧',earrings:'✧',bag:'▱',necklace:'♡',hair:'❋',hairColor:'◒',eyes:'◉',lip:'♡',skin:'◕'};
const skinColors=['#f5d3bd','#dba574','#b57955','#744a38'],hairColors=['#68412d','#29222c','#dba74d','#ad4d30'],eyeColors=['#69402c','#4485b0','#528268','#b38939'],lipColors=['#bd7976','#d25c8a','#dc7c69','#984b72'];
function avatar(s=look,interactive=false){
 const skin=skinColors[s.skin],hair=hairColors[s.hairColor],eye=eyeColors[s.eyes],lip=lipColors[s.lip],top=['#faf2e5','#d69cbd','#9fbdd6','#a58bc9'][s.top],skirt=['#7899bb','#efd2df','#a8c7b9','#c6b2e3'][s.skirt];
 const hit=(part,label,shape)=>interactive?`<g class="face-hit" role="button" tabindex="0" aria-label="${label}" data-face="${part}"><title>${label}</title>${shape}</g>`:'';
 let backHair=[`<path d="M103 148 Q73 48 150 43 Q231 45 199 218 L177 242 116 225Z"/>`,`<path d="M105 180 Q58 148 83 111 Q62 71 102 60 Q117 25 151 43 Q184 25 202 64 Q241 75 218 113 Q246 151 197 202Z"/>`,`<circle cx="94" cy="69" r="28"/><circle cx="207" cy="69" r="28"/><path d="M95 140V93Q95 42 150 45Q210 42 207 141Z"/>`,`<path d="M91 146V96Q91 38 150 42Q211 39 211 147L186 177 107 165Z"/>`][s.hair];
 let shoes=[`<path d="M119 448L117 469Q96 470 95 481H142V449M163 449V481H210Q207 470 185 467L183 448" fill="#fffaf5"/><path d="M96 480H142M164 480H210M119 464H134M171 464H184" stroke="#b18ac6" stroke-width="4"/>`,`<path d="M116 463Q97 471 101 481H142V460Q129 471 116 463M164 460V481H202Q206 470 185 462Q177 472 164 460" fill="#d991ad"/><path d="M117 475l9-7 8 7M171 475l9-7 8 7" fill="none" stroke="#fff1f7" stroke-width="3"/>`,`<path d="M114 447V465Q95 468 96 482H142V447M164 447V482H211Q211 469 188 463V447" fill="#e8f4ef"/><path d="M98 477H140M165 477H209" stroke="#5c9d89" stroke-width="7"/>`,`<path d="M115 466Q101 469 102 481H142V467M164 467V481H202Q202 470 187 466" fill="#c59b59"/><path d="M118 450L139 467M139 450L118 468M167 450L185 468M185 450L167 468" stroke="#c59b59" stroke-width="5"/>`][s.shoes];
 const bags=[`<path d="M181 210L218 321" fill="none" stroke="#aa714c" stroke-width="5"/><rect x="199" y="306" width="43" height="42" rx="10" fill="#bc875f"/><path d="M201 317H240" stroke="#e3bd8e" stroke-width="3"/><circle cx="222" cy="326" r="3" fill="#f4d184"/>`,`<path d="M210 313Q211 284 233 313" fill="none" stroke="#c77699" stroke-width="5"/><rect x="199" y="307" width="45" height="39" rx="8" fill="#e8aac8"/><path d="M222 321q-22-16-15 6l15-6q22-16 15 6Z" fill="#fff0f5"/>`,`<rect x="201" y="290" width="42" height="57" rx="16" fill="#86ad9c"/><path d="M212 292q8-23 17 0" fill="none" stroke="#527d70" stroke-width="5"/><rect x="207" y="320" width="30" height="21" rx="7" fill="#bad6c8"/>`,`<path d="M203 315Q215 261 239 315" fill="none" stroke="#d2b674" stroke-width="3"/><rect x="198" y="311" width="47" height="29" rx="7" fill="#bea0d5"/><path d="M199 313L221 329 244 313" fill="none" stroke="#ecd9f2" stroke-width="2"/>`][s.bag];
 return `<svg class="girl" viewBox="${faceZoom&&interactive?'65 23 175 190':'0 0 300 510'}" xmlns="http://www.w3.org/2000/svg" role="${interactive?'group':'img'}" aria-label="Menina com o visual escolhido"><ellipse cx="150" cy="487" rx="75" ry="9" fill="#bba0ba" opacity=".17"/><g fill="${hair}">${backHair}</g><g fill="${skin}" stroke="#714a40" stroke-opacity=".14" stroke-width="1.5"><path d="M118 332L116 468Q128 478 141 467L147 344M156 344L164 468Q179 477 188 466L184 332Z"/><path d="M113 197Q93 200 87 231L71 299Q70 315 81 318Q94 317 96 302L112 255M188 197Q207 204 213 233L228 301Q230 316 219 319Q207 317 205 302L189 254"/><path d="M135 164V194L119 204Q150 230 183 204L166 193V164"/><ellipse cx="98" cy="124" rx="9" ry="15"/><ellipse cx="202" cy="124" rx="9" ry="15"/><path d="M99 96Q99 59 150 58Q202 59 202 99L196 145Q186 178 150 182Q114 177 104 147Z"/></g><path d="M112 197L134 188Q150 207 167 188L190 198 201 228 185 237 183 281H116L113 237 98 228Z" fill="${top}" stroke="#7e5b87" stroke-opacity=".15" stroke-width="2"/>${s.top===1?'<path d="M116 197Q129 219 150 201Q171 219 184 197" fill="none" stroke="#fff6f9" stroke-width="9"/>':s.top===2?'<path d="M150 202V280M116 247H134M167 247H183" stroke="#fff" stroke-width="4"/>':s.top===3?'<path d="M119 212L150 225 182 212" fill="none" stroke="#e9d6ac" stroke-width="4"/><circle cx="150" cy="227" r="5" fill="#f0d39a"/>':'<path d="M142 224q-12-15-17-2q-2 9 17 19q20-14 16-21q-7-11-16 4" fill="#c5a5d6"/>'}<path d="M116 273H184L${s.skirt===3?'214 358Q150 380 87 358':'202 349Q150 366 98 349'}Z" fill="${skirt}" stroke="#7e5b87" stroke-opacity=".15" stroke-width="2"/><path d="M116 278H184" stroke="#fff" stroke-opacity=".7" stroke-width="7"/>${s.skirt===0?'<path d="M151 282V354M117 290q0 22 18 16M184 290q0 22-18 16" fill="none" stroke="#d7e7ef" stroke-width="2"/>':s.skirt===1?[120,150,180].map((x,i)=>`<text x="${x}" y="${319+i%2*20}" fill="#fff8f3" font-size="22">✿</text>`).join(''):`<path d="M127 285L116 350M144 285L140 358M160 285L166 359M175 285L189 350" stroke="#fff" stroke-opacity=".5" stroke-width="3"/>`}${shoes}<g fill="none" stroke="${hair}" stroke-width="4" stroke-linecap="round"><path d="M116 110Q125 106 135 110M166 110Q177 106 185 110"/></g><g fill="#fff"><ellipse cx="126" cy="123" rx="12" ry="9"/><ellipse cx="176" cy="123" rx="12" ry="9"/></g><g fill="${eye}"><ellipse cx="128" cy="123" rx="6" ry="8"/><ellipse cx="174" cy="123" rx="6" ry="8"/></g><g fill="#332b33"><ellipse cx="129" cy="124" rx="3" ry="5"/><ellipse cx="173" cy="124" rx="3" ry="5"/></g><g fill="white"><circle cx="130" cy="120" r="2"/><circle cx="175" cy="120" r="2"/></g><path d="M115 120q10-11 22 0M165 120q10-11 22 0" fill="none" stroke="#493533" stroke-width="2.5"/><path d="M149 129q-5 12 3 12" fill="none" stroke="#b27763" stroke-width="2"/><ellipse cx="116" cy="143" rx="10" ry="5" fill="#df8b91" opacity=".25"/><ellipse cx="185" cy="143" rx="10" ry="5" fill="#df8b91" opacity=".25"/><path d="M138 154Q145 148 151 152Q157 149 165 153Q152 167 138 154" fill="${lip}"/><path d="M143 154Q152 157 160 154" stroke="#fff3e9" fill="none" stroke-width="1.5"/><g fill="${hair}"><path d="M99 105Q91 53 148 50Q208 47 204 105Q181 93 171 73Q144 106 99 105Z"/>${s.hair===1?'<circle cx="99" cy="99" r="15"/><circle cx="202" cy="98" r="15"/><circle cx="102" cy="76" r="19"/><circle cx="195" cy="73" r="19"/>':''}</g>${[98,202].map(x=>s.earrings===0?`<circle cx="${x}" cy="142" r="4" fill="#fff9ec"/>`:s.earrings===1?`<path d="M${x} 143q-12-12-9 1l9 10 9-10q3-13-9-1" fill="#d58aaf"/>`:s.earrings===2?`<text x="${x-8}" y="155" font-size="21" fill="#d1aa51">★</text>`:`<ellipse cx="${x}" cy="149" rx="6" ry="9" fill="none" stroke="#c9a34c" stroke-width="3"/>`).join('')}${s.necklace?`<path d="M130 192Q150 231 173 192" fill="none" stroke="${s.necklace===2?'#ca89ae':'#c9a34c'}" stroke-width="${s.necklace===2?5:2}"/><text x="143" y="224" font-size="17" fill="#c9a34c">${s.necklace===3?'★':'♥'}</text>`:''}${bags}${hit('hair','Mudar o cabelo','<path d="M85 95V34H220V95Z"/>')}${hit('eyes','Mudar os olhos','<rect x="110" y="106" width="81" height="29" rx="8"/>')}${hit('lip','Mudar o batom','<rect x="130" y="146" width="42" height="25" rx="10"/>')}${hit('earrings','Mudar os brincos','<rect x="86" y="135" width="22" height="30"/><rect x="194" y="135" width="22" height="30"/>')}</svg>`;
}
function fashion(){document.body.dataset.section='fashion';app.innerHTML=`<section class="fashion-page"><div class="fashion-heading"><button class="back" id="fashion-back">← Todos os jogos</button><span>SEU PEQUENO ATELIÊ</span><h1>Moda <i>&</i> Estilo</h1><p>Um mundo de cores. Um look do seu jeitinho.</p></div><div class="atelier"><section class="dressing-room"><div class="mirror-label">✧ Espelho, espelho meu ✧</div><div id="avatar-stage"></div><div class="zoom-controls"><button id="full-body">↔ Corpo inteiro</button><button id="zoom-face">♡ Ver o rosto</button></div><p class="mirror-tip">Toque no cabelo, nos olhos ou na boca para mudar.</p></section><section class="wardrobe"><div class="wardrobe-head"><div><small>MISTURE E COMBINE</small><h2>Meu guarda-roupa</h2></div><span>✿</span></div><div class="style-presets">${['Casual','Romântico','Esportivo','Festa'].map((n,i)=>`<button data-preset="${i}">${n}</button>`).join('')}</div><div class="category-tabs" role="group" aria-label="Categorias">${Object.keys(fashionOptions).map(k=>`<button data-category="${k}">${fashionLabels[k]}</button>`).join('')}</div><div id="fashion-options"></div><div class="look-actions"><button id="save-look">♡ Salvar meu look</button><button id="reset-look">Recomeçar</button></div><p class="save-note">Seu look fica guardado neste navegador.</p></section></div></section>`;
 $('#fashion-back').onclick=home;$('#full-body').onclick=()=>{faceZoom=false;drawFashion()};$('#zoom-face').onclick=()=>{faceZoom=true;fashionCategory='hair';drawFashion()};
 document.querySelectorAll('[data-category]').forEach(b=>b.onclick=()=>{fashionCategory=b.dataset.category;faceZoom=['hair','hairColor','eyes','lip','earrings'].includes(fashionCategory);drawFashion()});
 document.querySelectorAll('[data-preset]').forEach(b=>b.onclick=()=>{const n=+b.dataset.preset;for(const k of ['top','skirt','shoes','earrings','bag','necklace'])look[k]=n;faceZoom=false;drawFashion();chime()});
 $('#save-look').onclick=()=>{try{localStorage.setItem('alice-isabela-look',JSON.stringify(look));notify('Look salvo! Ele estará aqui quando você voltar.')}catch{notify('Não foi possível salvar neste navegador.')}};
 $('#reset-look').onclick=()=>{look={...fashionDefault};faceZoom=false;drawFashion()};drawFashion();window.scrollTo(0,0);
}
function drawFashion(){
 $('#avatar-stage').innerHTML=avatar(look,true);$('#avatar-stage').classList.toggle('zoomed',faceZoom);
 document.querySelectorAll('[data-face]').forEach(b=>{const activate=()=>{faceZoom=true;fashionCategory=b.dataset.face;drawFashion()};b.onclick=activate;b.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();activate()}}});
 document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category===fashionCategory));
 const colors={skin:skinColors,hairColor:hairColors,eyes:eyeColors,lip:lipColors};
 $('#fashion-options').innerHTML=`<h3>${fashionLabels[fashionCategory]}</h3><div class="option-grid">${fashionOptions[fashionCategory].map((name,i)=>{let sample={...look,[fashionCategory]:i};let visual=colors[fashionCategory]?`<span class="color-sample" style="background:${colors[fashionCategory][i]}"></span>`:avatar(sample,false);return `<button class="look-option preview-${fashionCategory}" data-option="${i}" aria-pressed="${look[fashionCategory]===i}">${visual}<span>${name}</span></button>`}).join('')}</div>`;
 document.querySelectorAll('[data-option]').forEach(b=>b.onclick=()=>{look[fashionCategory]=+b.dataset.option;drawFashion();chime()});
}
home=function(){document.body.dataset.section='home';faceZoom=false;app.innerHTML=`<section class="portal"><div class="portal-stars" aria-hidden="true">✧ · ♡ · ✧</div><p class="portal-kicker">UM CANTINHO FEITO PARA VOCÊS</p><h1>Jogos de<br><span class="alice">Alice</span> <span class="and">e</span> <span class="isabela">Isabela</span></h1><p class="portal-subtitle">Duas irmãs. Mil histórias para inventar.</p><div class="game-cards"><button class="game-card toys-card" id="toys-section"><div class="game-cover"><img class="room-cover" src="assets/andy.png" alt="Quarto dos brinquedos"><img class="cover-woody" src="assets/toys/imported/woody-inert-v1.png" alt="Woody"><img class="cover-buzz" src="assets/toys/imported/buzz-lightyear-inert-v1.png" alt="Buzz Lightyear"><span class="cover-badge">⌕ ENCONTRE SEUS AMIGOS</span></div><div class="game-card-copy"><small>UMA AVENTURA EM CADA CANTINHO</small><h2>Brinquedos <span>↗</span></h2><p>Explore os quartos e encontre os brinquedos escondidos.</p></div></button><button class="game-card fashion-card" id="fashion-section"><div class="game-cover fashion-cover"><span class="fashion-spark one">✧</span><span class="fashion-spark two">✿</span>${avatar(fashionDefault)}<span class="cover-badge">♡ CRIE SEU LOOK</span></div><div class="game-card-copy"><small>SEU MUNDO DE CORES E BELEZA</small><h2>Moda e Estilo <span>↗</span></h2><p>Roupas, cabelos e acessórios para soltar a imaginação.</p></div></button></div><p class="portal-bottom">Feito com carinho, para brincar sem pressa. ♡</p></section>`;$('#toys-section').onclick=()=>choose('search');$('#fashion-section').onclick=fashion;window.scrollTo(0,0)};
const toyChoose=choose;choose=function(){document.body.dataset.section='toys';toyChoose('search');const status=app.querySelector('.status');if(status)status.textContent='Escolha seu quarto favorito e encontre os cinco brinquedos da lista.'};
document.title='Jogos de Alice e Isabela';$('.brand').innerHTML='<span class="brand-star">✿</span><span>JOGOS DE<br><b><span class="alice">Alice</span> e <span class="isabela">Isabela</span></b></span>';
document.querySelector('footer').innerHTML='Um cantinho de imaginação para Alice e Isabela <span>♡</span> Feito para brincar juntas';
home();
